mapper.sql:
FROM trade_order_publication_issue pi
INNER JOIN trade_order o ON o.id = pi.order_id AND o.deleted = FALSE
WHERE pi.deleted = FALSE
  AND pi.canceled = FALSE
  AND o.status = #{orderStatus}
  AND pi.delivery_status = #{publicationDeliveryStatus}

  AND pi.delivery_type = #{reqVO.deliveryType}


  AND pi.school_id = #{reqVO.schoolId}


  AND pi.station_id = #{reqVO.stationId}


  AND pi.window_id = #{reqVO.windowId}


  AND pi.offer_id = #{reqVO.offerId}


  AND pi.offer_sku_id = #{reqVO.offerSkuId}


  AND pi.sku_id = #{reqVO.skuId}


  AND pi.issue_id = #{reqVO.issueId}


  AND pi.issue_no = #{reqVO.issueNo}

mapper.select:
SELECT pi.id AS orderIssueId, pi.order_id AS orderId, pi.order_no AS orderNo, pi.order_item_id AS orderItemId, pi.delivery_id AS deliveryId, pi.user_id AS userId, pi.delivery_type AS deliveryType, pi.count AS count, pi.school_id AS schoolId, pi.school_name_snapshot AS schoolNameSnapshot, pi.station_id AS stationId, pi.station_name_snapshot AS stationNameSnapshot, pi.window_id AS windowId, pi.window_name_snapshot AS windowNameSnapshot, pi.offer_id AS offerId, pi.offer_sku_id AS offerSkuId, pi.sku_id AS skuId, pi.product_name_snapshot AS productNameSnapshot, pi.student_id AS studentId, pi.student_name_snapshot AS studentNameSnapshot, pi.class_id AS classId, pi.class_name_snapshot AS classNameSnapshot, pi.issue_id AS issueId, pi.issue_no AS issueNo, pi.issue_name AS issueName, pi.planned_delivery_date AS plannedDeliveryDate
ORDER BY pi.order_id ASC, pi.order_item_id ASC, pi.issue_no ASC, pi.id ASC
LIMIT #{limit}

SELECT COUNT(1)
FROM trade_order_publication_issue
WHERE deleted = FALSE
  AND canceled = FALSE
  AND delivery_id = #{deliveryId}
  AND delivery_status <> #{deliveredStatus}

SELECT COUNT(1)
FROM trade_order_publication_issue
WHERE deleted = FALSE
  AND canceled = FALSE
  AND delivery_id = #{deliveryId}
  AND receive_status <> #{receivedStatus}

SELECT *
FROM trade_order_publication_issue
WHERE deleted = FALSE
  AND canceled = FALSE
  AND delivery_id = #{deliveryId}
  AND delivery_status = #{deliveredStatus}
  AND receive_status = #{unreceivedStatus}
ORDER BY issue_no ASC, id ASC

SELECT *
FROM trade_order_publication_issue
WHERE deleted = FALSE
  AND canceled = FALSE
  AND delivery_status = #{deliveredStatus}
  AND receive_status = #{unreceivedStatus}
  AND delivery_time IS NOT NULL
  AND delivery_time <= #{expireTime}
ORDER BY delivery_time ASC, id ASC
